solution.solution.cpp:
#include <cstdint>
#include <cstdio>
#include <string>

struct Ioctl { std::uint32_t deviceType, access, function, method; };

std::uint32_t ctlCode(std::uint32_t deviceType, std::uint32_t function, std::uint32_t method, std::uint32_t access)
{
    return (deviceType << 16) | (access << 14) | (function << 2) | method;
}

Ioctl decode(std::uint32_t code)
{
    return { code >> 16, (code >> 14) & 3u, (code >> 2) & 0xFFFu, code & 3u };
}

std::string describe(std::uint32_t code)
{
    const Ioctl i{ decode(code) };
    const char* methods[]{ "METHOD_BUFFERED", "METHOD_IN_DIRECT", "METHOD_OUT_DIRECT", "METHOD_NEITHER" };
    const char* access[]{ "FILE_ANY_ACCESS", "FILE_READ_DATA", "FILE_WRITE_DATA", "FILE_READ_DATA|FILE_WRITE_DATA" };
    char buffer[160];
    std::snprintf(buffer, sizeof(buffer), "device 0x%04X, function 0x%03X, %s, %s", i.deviceType, i.function, methods[i.method], access[i.access]);
    return buffer;
}

bool accessAllowed(std::uint32_t code, std::uint32_t handleAccess)
{
    const std::uint32_t needed{ decode(code).access };
    return (needed & ~handleAccess) == 0;
}

unitTests:
TEST("packing") {
    CHECK_EQ(ctlCode(0x8000, 0x800, 0, 0), 0x80002000u); CHECK_EQ(ctlCode(0x8000, 0x801, 0, 1), 0x80006004u);
    CHECK_EQ(ctlCode(0x22, 0x802, 2, 2), 0x0022A00Au); CHECK_EQ(ctlCode(0x8000, 0x803, 3, 3), 0x8000E00Fu);
}
TEST("unpacking") { const Ioctl i = decode(0x8000E00Fu); CHECK_EQ(i.deviceType, 0x8000u); CHECK_EQ(i.function, 0x803u); CHECK_EQ(i.method, 3u); CHECK_EQ(i.access, 3u); }
TEST("descriptions") {
    CHECK_EQ(describe(0x80002000u), std::string("device 0x8000, function 0x800, METHOD_BUFFERED, FILE_ANY_ACCESS"));
    CHECK_EQ(describe(0x0022A00Au), std::string("device 0x0022, function 0x802, METHOD_OUT_DIRECT, FILE_WRITE_DATA"));
    CHECK_EQ(describe(ctlCode(0x8000, 0x10, 1, 3)), std::string("device 0x8000, function 0x010, METHOD_IN_DIRECT, FILE_READ_DATA|FILE_WRITE_DATA"));
}
TEST("access") {
    CHECK(accessAllowed(0x80002000u, 0)); CHECK(accessAllowed(0x80006004u, 1)); CHECK(!accessAllowed(0x80006004u, 2));
    CHECK(!accessAllowed(0x8000E00Fu, 1)); CHECK(accessAllowed(0x8000E00Fu, 3));
}

